t.script:
document.addEventListener('DOMContentLoaded', function() {
    // Technical issue toggle
    var toggle = document.getElementById('has_technical_issues');
    var fields = document.getElementById('tech_issue_fields');
    if (toggle && fields) {
        function updateFields() { fields.style.display = toggle.checked ? 'block' : 'none'; }
        toggle.addEventListener('change', updateFields);
        updateFields();
    }

    // Lesson summary required asterisks: hide when all students absent
    function updateSummaryRequired() {
        var radios = document.querySelectorAll('.tm-att-radio input[type="radio"]');
        var studentIds = {};
        radios.forEach(function(r) { studentIds[r.name] = true; });
        var allAbsent = Object.keys(studentIds).length > 0 && Object.keys(studentIds).every(function(name) {
            var checked = document.querySelector('.tm-att-radio input[name="' + name + '"]:checked');
            return checked && checked.value === 'absent';
        });
        document.querySelectorAll('.tm-summary-required').forEach(function(el) {
            el.style.display = allAbsent ? 'none' : 'inline';
        });
        document.getElementById('topic_covered').required = !allAbsent;
        var ratingInputs = document.querySelectorAll('input[name="class_rating"]');
        ratingInputs.forEach(function(r) { r.required = !allAbsent; });
    }
    document.querySelectorAll('.tm-att-radio input[type="radio"]').forEach(function(r) {
        r.addEventListener('change', updateSummaryRequired);
    });
    updateSummaryRequired();
});

div.script:

// ── Type toggle ──────────────────────────────────────────
function setAssignmentMode(mode) {
    document.getElementById('asgn_mode_input').value = mode;
    var assigned = document.getElementById('type-assigned');
    var control  = document.getElementById('type-control');
    if (mode === 'assigned') {
        assigned.style.background = '#fff';
        assigned.style.color = '#333';
        assigned.style.fontWeight = '600';
        control.style.background = 'transparent';
        control.style.color = '#888';
        control.style.fontWeight = '500';
    } else {
        control.style.background = '#fff';
        control.style.color = '#333';
        control.style.fontWeight = '600';
        assigned.style.background = 'transparent';
        assigned.style.color = '#888';
        assigned.style.fontWeight = '500';
    }
}

// ── Placeholder for editor ────────────────────────────────
var _editor = document.getElementById('asgn_description_editor');
if (_editor) {
    _editor.addEventListener('focus', function() {
        if (this.innerHTML === '' || this.innerHTML === '<br>') this.innerHTML = '';
    });
    _editor.addEventListener('input', function() {
        document.getElementById('asgn_description_hidden').value = this.innerHTML;
    });
    // show placeholder via CSS
    var st = document.createElement('style');
    st.innerHTML = '#asgn_description_editor:empty:before{content:attr(data-placeholder);color:#aaa;}';
    document.head.appendChild(st);
}

// ── Link insert ──────────────────────────────────────────
function asgnInsertLink() {
    var url = prompt('Enter URL:');
    if (url) document.execCommand('createLink', false, url);
}

// ── File handling ────────────────────────────────────────
var _asgnFiles = [];
function asgnHandleFiles(fileList) {
    Array.from(fileList).forEach(function(f) { _asgnFiles.push(f); });
    asgnRenderFileList();
}
function asgnHandleDrop(e) {
    e.preventDefault();
    document.getElementById('asgn_drop_zone').style.borderColor = '#d0d7de';
    asgnHandleFiles(e.dataTransfer.files);
}
function asgnRenderFileList() {
    var list = document.getElementById('asgn_file_list');
    list.innerHTML = '';
    if (_asgnFiles.length === 0) return;
    var grid = document.createElement('div');
    grid.style.cssText = 'display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px;';
    _asgnFiles.forEach(function(f) {
        var item = document.createElement('div');
        item.style.cssText = 'background:#f8f9fa;border:1px solid #e8eaed;border-radius:8px;padding:8px 10px;';
        item.innerHTML =
            '<div style="display:flex;justify-content:space-between;font-size:12px;color:#555;margin-bottom:4px;">' +
            '<span>' + f.name + ' [100%]</span><span>100%</span></div>' +
            '<div style="height:4px;background:#e0e0e0;border-radius:4px;overflow:hidden;">' +
            '<div style="width:100%;height:100%;background:#4caf50;border-radius:4px;"></div></div>';
        grid.appendChild(item);
    });
    list.appendChild(grid);
}

// ── Submit handler ───────────────────────────────────────
function asgnPrepareSubmit(isDraft) {
    var editor = document.getElementById('asgn_description_editor');
    var descVal = editor ? editor.innerText.trim() : '';
    var typeVal = document.querySelector('[name="assignment_type"]').value;
    var nameVal = document.querySelector('[name="name"]').value.trim();

    if (!nameVal) {
        alert('Assignment Title is required.');
        document.querySelector('[name="name"]').focus();
        return;
    }
    if (!typeVal) {
        alert('Assignment Type is required.');
        document.querySelector('[name="assignment_type"]').focus();
        return;
    }
    if (!descVal) {
        alert('Description / Instructions is required.');
        editor.focus();
        return;
    }

    document.getElementById('asgn_draft_flag').value = isDraft ? '1' : '0';
    if (editor) {
        document.getElementById('asgn_description_hidden').value = editor.innerHTML;
    }
    document.getElementById('asgn-create-form').submit();
}


function toggleEditPanel() {
    var view = document.getElementById('asgn_view_panel');
    var edit = document.getElementById('asgn_edit_panel');
    if (edit.style.display === 'none') {
        view.style.display = 'none';
        edit.style.display = 'block';
        // Seed editor with saved description
        var hidden = document.getElementById('asgn_edit_hidden');
        var editor = document.getElementById('asgn_edit_editor');
        if (editor && hidden && !editor._seeded) {
            editor.innerHTML = hidden.value;
            editor._seeded = true;
        }
    } else {
        edit.style.display = 'none';
        view.style.display = 'block';
    }
}
// Auto-open edit panel if ?edit=1 in URL
if (window.location.search.indexOf('edit=1') !== -1) {
    document.addEventListener('DOMContentLoaded', function() { toggleEditPanel(); });
}

// ── Edit editor ────────────────────────────────
(function() {
    var editor = document.getElementById('asgn_edit_editor');
    if (!editor) return;
    var hidden = document.getElementById('asgn_edit_hidden');
    // placeholder
    var st = document.createElement('style');
    st.innerHTML = '#asgn_edit_editor:empty:before{content:attr(data-placeholder);color:#aaa;}';
    document.head.appendChild(st);
    editor.addEventListener('input', function() {
        hidden.value = this.innerHTML;
    });
})();

function asgnEditInsertLink() {
    var url = prompt('Enter URL:');
    if (url) document.execCommand('createLink', false, url);
}

// ── Edit file drop ──────────────────────────────
var _editFiles = [];
function asgnEditHandleFiles(fileList) {
    Array.from(fileList).forEach(function(f) { _editFiles.push(f); });
    asgnEditRenderFileList();
}
function asgnEditHandleDrop(e) {
    e.preventDefault();
    document.getElementById('asgn_edit_drop_zone').style.borderColor = '#d0d7de';
    asgnEditHandleFiles(e.dataTransfer.files);
}
function asgnEditRenderFileList() {
    var list = document.getElementById('asgn_edit_file_list');
    list.innerHTML = '';
    if (_editFiles.length === 0) return;
    var grid = document.createElement('div');
    grid.style.cssText = 'display:grid;grid-template-columns:1fr;gap:6px;margin-bottom:8px;';
    _editFiles.forEach(function(f) {
        var item = document.createElement('div');
        item.style.cssText = 'background:#f8f9fa;border:1px solid #e8eaed;border-radius:8px;padding:6px 10px;font-size:12px;color:#555;';
        item.innerHTML = '<i class="fa fa-paperclip" style="color:#4a6cf7;margin-right:6px;"/>' + f.name;
        grid.appendChild(item);
    });
    list.appendChild(grid);
}

// ── Edit submit ──────────────────────────────────
function asgnEditSubmit() {
    var editor = document.getElementById('asgn_edit_editor');
    var hidden = document.getElementById('asgn_edit_hidden');
    var descVal = editor ? editor.innerText.trim() : '';
    var nameVal = document.querySelector('#asgn-edit-form [name="name"]').value.trim();
    var typeVal = document.querySelector('#asgn-edit-form [name="assignment_type"]').value;

    if (!nameVal) {
        alert('Assignment Title is required.');
        return;
    }
    if (!typeVal) {
        alert('Assignment Type is required.');
        return;
    }
    if (!descVal) {
        alert('Description / Instructions is required.');
        editor && editor.focus();
        return;
    }
    if (editor) hidden.value = editor.innerHTML;
    document.getElementById('asgn-edit-form').submit();
}
